39	#[derive(Debug, Default)]
40	struct TestFiles {
41	    unreferenced: Vec<PathBuf>,
42	    updated: Vec<PathBuf>,
43	}
44	
45	impl TestFiles {
46	    fn is_empty(&self) -> bool {
47	        self.unreferenced.is_empty() && self.updated.is_empty()
48	    }
49	}
