58	impl fmt::Display for TestFiles {
59	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
60	        if self.is_empty() {
61	            writeln!(f, "No unreferenced or updated test files found")
62	        } else {
63	            let root_dir = project_root();
64	            if !self.unreferenced.is_empty() {
65	                writeln!(
66	                    f,
67	                    "Unreferenced test files found for which no comment exists:",
68	                )?;
69	                for path in &self.unreferenced {
70	                    writeln!(f, "  {}", path.strip_prefix(&root_dir).unwrap().display())?;
71	                }
72	                writeln!(f, "Please delete these files manually")?;
73	            }
74	            if !self.updated.is_empty() {
75	                if !self.unreferenced.is_empty() {
76	                    writeln!(f)?;
77	                }
78	                writeln!(
79	                    f,
80	                    "Following files were not up-to date and has been updated:",
81	                )?;
82	                for path in &self.updated {
83	                    writeln!(f, "  {}", path.strip_prefix(&root_dir).unwrap().display())?;
84	                }
85	                writeln!(
86	                    f,
87	                    "Re-run the tests with `cargo test` to update the test snapshots"
88	                )?;
89	                if std::env::var("CI").is_ok() {
90	                    writeln!(
91	                        f,
92	                        "NOTE: Run the tests locally and commit the updated files"
93	                    )?;
94	                }
95	            }
96	            Ok(())
97	        }
98	    }
99	}
