137	#[derive(Default, Debug)]
138	struct TestCollection {
139	    ok: HashMap<String, Test>,
140	    err: HashMap<String, Test>,
141	}
142	
143	impl TryFrom<&Path> for TestCollection {
144	    type Error = anyhow::Error;
145	
146	    fn try_from(path: &Path) -> Result<Self> {
147	        let mut tests = TestCollection::default();
148	
149	        for entry in walkdir::WalkDir::new(path) {
150	            let entry = entry?;
151	            if !entry.file_type().is_file() {
152	                continue;
153	            }
154	            if entry.path().extension().unwrap_or_default() != "rs" {
155	                continue;
156	            }
157	            let text = fs::read_to_string(entry.path())?;
158	            for test in collect_tests(&text) {
159	                if test.is_ok() {
160	                    if let Some(old_test) = tests.ok.insert(test.name.clone(), test) {
161	                        anyhow::bail!(
162	                            "Duplicate test found: {name:?} (search '// test_ok {name}' for the location)\n",
163	                            name = old_test.name
164	                        );
165	                    }
166	                } else if let Some(old_test) = tests.err.insert(test.name.clone(), test) {
167	                    anyhow::bail!(
168	                        "Duplicate test found: {name:?} (search '// test_err {name}' for the location)\n",
169	                        name = old_test.name
170	                    );
171	                }
172	            }
173	        }
174	
175	        Ok(tests)
176	    }
177	}
